import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    intervals = [[] for _ in range(n + 1)]
    at = 2
    for _ in range(m):
        l, r, x = data[at], data[at + 1], data[at + 2]
        at += 3
        intervals[x].append((l, r))

    inf = n + 1
    # For each x and left endpoint l, store the minimum right endpoint
    # of a constraint assigned to x whose left endpoint is at least l.
    min_right = [[inf] * (n + 1) for _ in range(n + 1)]
    for x in range(1, n + 1):
        exact = [inf] * (n + 1)
        for l, r in intervals[x]:
            if r < exact[l]:
                exact[l] = r
        best = inf
        row = min_right[x]
        for l in range(x, 0, -1):
            if exact[l] < best:
                best = exact[l]
            row[l] = best

    choose = [[0] * (n + 1) for _ in range(n + 1)]
    choose[0][0] = 1
    for i in range(1, n + 1):
        choose[i][0] = choose[i][i] = 1
        prev, row = choose[i - 1], choose[i]
        for j in range(1, i):
            row[j] = (prev[j - 1] + prev[j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for l in range(1, n + 2):
        dp[l][l - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            for x in range(l, r + 1):
                if min_right[x][l] <= r:
                    continue
                total += choose[length - 1][x - l] * dp[l][x - 1] * dp[x + 1][r]
                total %= MOD
            dp[l][r] = total

    print(dp[1][n] % MOD)

if __name__ == '__main__':
    main()

