def alg(s):
 p=[i for i,x in enumerate(s) if x]
 if len(p)<=1:return 0
 q=[x-i for i,x in enumerate(p)]
 m=sorted(q)[len(q)//2]
 return sum(abs(x-m) for x in q)
def brute(s):
