def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 if not data: return
 n=data[0]; a=data[1:]
 M=max(a)
 phi=list(range(M+1))
 for p in range(2,M+1):
  if phi[p]==p:
   for k in range(p,M+1,p): phi[k]-=phi[k]//p
 spf=list(range(M+1))
 for p in range(2,int(M**0.5)+1):
  if spf[p]==p:
   for k in range(p*p,M+1,p):
    if spf[k]==k: spf[k]=p
 cache={}; sums=[0]*(M+1); ans=0; w=1; out=[]
 for x in a:
  ds=cache.get(x)
  if ds is None:
   t=x; factors=[]
   while t>1:
    p=spf[t]; e=0
    while t%p==0: t//=p; e+=1
    factors.append((p,e))
   ds=[1]
   for p,e in factors:
    old=ds[:]; q=1
    for _ in range(e):
     q*=p; ds.extend(d*q for d in old)
   cache[x]=ds
  c=0
  for d in ds:
   s=sums[d]; c+=phi[d]*s; sums[d]=s+w
   if sums[d]>=MOD: sums[d]-=MOD
  ans=(2*ans+c)%MOD; out.append(str(ans))
  w=(w*2)%MOD
 sys.stdout.write('\n'.join(out))
