import sys
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    N,M,K=data[:3]
    A=data[3:]
    S=1<<20
    # Walsh transform of x^K
    f=[pow(x,K,MOD) for x in range(S)]
    h=1
    while h<S:
        step=h<<1
        for i in range(0,S,step):
            for j in range(i,i+h):
                x,y=f[j],f[j+h]
                f[j]=(x+y)%MOD
                f[j+h]=(x-y)%MOD
        h=step
    # Walsh transform of the frequency table of input values
    freq=[0]*S
    for x in A: freq[x]+=1
    h=1
    while h<S:
        step=h<<1
        for i in range(0,S,step):
            for j in range(i,i+h):
                x,y=freq[j],freq[j+h]
                freq[j]=x+y
                freq[j+h]=x-y
        h=step
    hist=[0]*(N+1)
    for mask,s in enumerate(freq):
        p=(N+s)//2
        hist[p]=(hist[p]+f[mask])%MOD
    def mul(a,b):
        c=[0]*M
        for i,x in enumerate(a):
            if x:
                for j,y in enumerate(b):
                    if y: c[(i+j)%M]=(c[(i+j)%M]+x*y)%MOD
        return c
    def power_linear(sign,e):
        # (1 + sign*z)^e in Z[z]/(z^M-1)
        r=[0]*M; r[0]=1
        b=[0]*M; b[0]=1
        b[1%M]= (b[1%M]+sign)%MOD
        while e:
            if e&1: r=mul(r,b)
            e//=2
            if e: b=mul(b,b)
        return r
    cache={}
    ans=0
    for p,v in enumerate(hist):
        if not v: continue
        if p not in cache:
            a=power_linear(1,p)
            b=power_linear(-1,N-p)
            cache[p]=mul(a,b)[0]
        ans=(ans+v*cache[p])%MOD
    ans=ans*pow(S,MOD-2,MOD)%MOD
    print(ans)
