from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Group each pair by its larger endpoint. Once the sweep reaches r,
        # all such pairs impose a lower bound on the left endpoint.
        ends = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ends[b].append((a, idx))

        # Keep the two largest lower-endpoint values among pairs seen so far.
        # The first pair attaining the maximum is tracked only when unique.
        best_x = second_x = 0
        best_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for x, idx in ends[r]:
                if x > best_x:
                    second_x = best_x
                    best_x = x
                    best_id = idx
                elif x == best_x:
                    second_x = best_x
                    best_id = -1
                elif x > second_x:
                    second_x = x

            # With all pairs present, valid starts for a subarray ending at r
            # are best_x + 1 through r.
            total += r - best_x
            if best_id != -1:
                gains[best_id] += best_x - second_x

        return total + max(gains)

