def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    budget = next(it)
    processes = [(next(it), next(it), next(it), next(it)) for _ in range(n)]

    def feasible(target):
        total = 0
        for a, p, b, q in processes:
            g = gcd(a, b)
            best = 10**30
            if a * q >= b * p:  # S has no worse cost per unit of capacity
                # An optimal solution needs fewer than a/g T machines.
                for t in range(a // g):
                    s = max(0, (target - t * b + a - 1) // a)
                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            else:
                # T has better cost per unit; fewer than b/g S machines suffice.
                for s in range(b // g):
                    t = max(0, (target - s * a + b - 1) // b)
                    cost = s * p + t * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    low, high = 0, budget * 100 + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)

