from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # steps[x] is the number of popcount operations needed to reach 1.
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]

        # An integer with j set bits first becomes j after one operation.
        eligible = [False] * (length + 1)
        for j in range(1, length + 1):
            eligible[j] = steps[j] + 1 <= k

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                # Choose 0 here, then choose the needed number of 1s in the suffix.
                for j in range(1, length + 1):
                    if eligible[j]:
                        needed = j - prefix_ones
                        if 0 <= needed <= remaining:
                            answer += comb(remaining, needed)
                prefix_ones += 1

        return answer % mod

