def neigh(i,H,W):
 r,c=divmod(i,W)
 return [rr*W+cc for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<H and 0<=cc<W]

def brute(a,H,W,X,start):
 # Explore all possible absorbed subsets/order states to find max
