import sys
import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    H, W, X = data[0], data[1], data[2]
    P, Q = data[3] - 1, data[4] - 1
    strengths = data[5:]

    start = P * W + Q
    power = strengths[start]
    seen = bytearray(H * W)
    seen[start] = 1
    boundary = []

    def add(cell):
        if not seen[cell]:
            seen[cell] = 1
            heapq.heappush(boundary, (strengths[cell], cell))

    if P > 0:
        add(start - W)
    if P + 1 < H:
        add(start + W)
    if Q > 0:
        add(start - 1)
    if Q + 1 < W:
        add(start + 1)

    while boundary:
        strength, cell = boundary[0]
        if strength * X >= power:
            break
        heapq.heappop(boundary)
        power += strength
        row, col = divmod(cell, W)
        if row > 0:
            add(cell - W)
        if row + 1 < H:
            add(cell + W)
        if col > 0:
            add(cell - 1)
        if col + 1 < W:
            add(cell + 1)

    print(power)

if __name__ == "__main__":
    main()

