def mountain(x):
    # crease indices are positive
    if x <= 0:
        return 0
    t = (x & -x).bit_length() - 1
    return 1 - ((x >> (t + 1)) & 1)

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]; a=data[1:]
    # Search many low positions, plus positions aligned around each input offset.
    best=0
    lim=1 << 19
    for i in range(1,lim+1):
        s=0
        for x in a:
            s += mountain(i+x)
        if s>best: best=s
    # Candidate probes at offsets and nearby binary boundaries.
    cand=set([1])
    for x in a:
        for y in (x, x+1, max(1,x-1)):
            for b in range(61):
                q=(y//(1<<b))*(1<<b)
                for i in (q, q+1, q+(1<<b), q-(1<<b)):
                    if 1<=i<=10**18: cand.add(i)
    for i in cand:
        s=sum(mountain(i+x) for x in a)
        if s>best: best=s
    print(best)
