import sys
import math

N = int(sys.stdin.buffer.readline())

# Any solution has d = x-y >= 1 and d^3 <= x^3-y^3 = N.
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d:
        continue
    # N/d = 3*y^2 + 3*d*y + d^2
    disc = 12 * (N // d) - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s == disc and (s - 3 * d) % 6 == 0:
        y = (s - 3 * d) // 6
        if y > 0:
            print(y + d, y)
            break
else:
    print(-1)

