from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        # Screen-coordinate directions in clockwise order.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        ans = 1 if any(1 in row for row in grid) else 0

        for d, (dr, dc) in enumerate(dirs):
            tr, tc = dirs[(d + 1) % 4]

            # Straight-run lengths in the direction used after the turn.
            straight0 = [0] * size
            straight2 = [0] * size
            rows = range(n - 1, -1, -1) if tr > 0 else range(n)
            cols = range(m - 1, -1, -1) if tc > 0 else range(m)
            for r in rows:
                for c in cols:
                    p = r * m + c
                    v = grid[r][c]
                    nr, nc = r + tr, c + tc
                    q = nr * m + nc if 0 <= nr < n and 0 <= nc < m else -1
                    if v == 0:
                        straight0[p] = 1 + (straight2[q] if q >= 0 else 0)
                    elif v == 2:
                        straight2[p] = 1 + (straight0[q] if q >= 0 else 0)

            # Best valid continuation in direction d, with at most one turn left.
            best0 = [0] * size
            best2 = [0] * size
            rows = range(n - 1, -1, -1) if dr > 0 else range(n)
            cols = range(m - 1, -1, -1) if dc > 0 else range(m)
